<?php

declare(strict_types=1);

require_once dirname(__DIR__) . '/helpers.php';
require_once dirname(__DIR__) . '/asterisk_sync.php';
require_once dirname(__DIR__) . '/repositories/DialplanRuleRepository.php';
require_once __DIR__ . '/DialplanRuleService.php';

/**
 * Inbound Call Normalization (/inbound-normalization): rewrites the caller's number or the dialled
 * number of incoming calls, for one trunk or all of them. Generated by SyncInboundDialplan.php.
 * With no rules nothing is added to the dialplan.
 */
final class InboundNormService
{
    public const TARGETS = ['caller', 'did'];

    /** @return list<array<string, mixed>> */
    public static function all(): array
    {
        return getDB()->query('SELECT * FROM pbx_inbound_norm_rules ORDER BY trunk_name IS NOT NULL, trunk_name, target, match_pattern')->fetchAll(PDO::FETCH_ASSOC);
    }

    /** @return list<string> */
    public static function trunkNames(): array
    {
        return getDB()->query('SELECT trunk_name FROM pbx_trunks ORDER BY trunk_name')->fetchAll(PDO::FETCH_COLUMN);
    }

    public static function isValidPattern(string $pattern): bool
    {
        if (!preg_match('/^(_[0-9NXZnxz.!*#+\[\]-]{1,39}|\+?[0-9*#]{1,39})$/D', $pattern)) {
            return false;
        }
        return substr_count($pattern, '[') === substr_count($pattern, ']');
    }

    public static function save(array $data): array
    {
        return PBXHelper::handleAction($data['csrf_token'] ?? '', function () use ($data) {
            $id = (int) ($data['rule_id'] ?? 0);
            $target = in_array($data['target'] ?? '', self::TARGETS, true) ? $data['target'] : 'caller';
            $name = mb_substr(trim((string) ($data['rule_name'] ?? '')), 0, 120);
            $pattern = trim((string) ($data['match_pattern'] ?? ''));
            $trunk = trim((string) ($data['trunk_name'] ?? ''));
            if ($name === '' || !self::isValidPattern($pattern)) {
                throw new \Exception(t('inbound_norm.err_pattern'));
            }
            if ($trunk !== '' && !in_array($trunk, self::trunkNames(), true)) {
                throw new \Exception(t('inbound_norm.err_trunk'));
            }
            $row = [
                $trunk !== '' ? $trunk : null,
                $target,
                $name,
                $pattern,
                max(0, min(20, (int) ($data['strip_front'] ?? 0))),
                substr((string) preg_replace('/[^0-9+*#]/', '', (string) ($data['prepend'] ?? '')), 0, 30),
                empty($data['is_active']) ? 0 : 1,
            ];
            $db = getDB();
            $same = $db->prepare('SELECT id FROM pbx_inbound_norm_rules WHERE trunk_name <=> ? AND target = ? AND match_pattern = ? AND id <> ?');
            $same->execute([$row[0], $target, $pattern, $id]);
            if ($same->fetchColumn() !== false) {
                throw new \Exception(t('inbound_norm.err_exists'));
            }
            if ($id > 0) {
                $row[] = $id;
                $db->prepare('UPDATE pbx_inbound_norm_rules SET trunk_name = ?, target = ?, rule_name = ?, match_pattern = ?, strip_front = ?, prepend = ?, is_active = ?, updated_at = NOW() WHERE id = ?')->execute($row);
            } else {
                $db->prepare('INSERT INTO pbx_inbound_norm_rules (trunk_name, target, rule_name, match_pattern, strip_front, prepend, is_active, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, NOW())')->execute($row);
            }
            self::markChanged($name, $id > 0 ? 'update' : 'create');
            return t('inbound_norm.saved');
        });
    }

    public static function delete(array $data): array
    {
        return PBXHelper::handleAction($data['csrf_token'] ?? '', function () use ($data) {
            $id = (int) ($data['rule_id'] ?? 0);
            getDB()->prepare('DELETE FROM pbx_inbound_norm_rules WHERE id = ?')->execute([$id]);
            self::markChanged("#{$id}", 'delete');
            return t('inbound_norm.deleted');
        });
    }

    /**
     * Ready-made rules of a country from its preset file. Only added when asked for: a new
     * installation has none.
     *
     * @return list<array<string, mixed>>
     */
    public static function presets(string $cc): array
    {
        $rules = [];
        foreach (DialplanRuleService::presetFile($cc)['inbound'] ?? [] as $r) {
            if (is_array($r) && in_array($r['target'] ?? '', self::TARGETS, true) && DialplanRuleService::presetRuleIsValid($r)) {
                $rules[] = $r;
            }
        }
        return $rules;
    }

    public static function loadPresets(array $data): array
    {
        return PBXHelper::handleAction($data['csrf_token'] ?? '', function () use ($data) {
            $cc = (string) preg_replace('/[^0-9]/', '', (string) ($data['country_code'] ?? ''));
            $trunk = trim((string) ($data['trunk_name'] ?? ''));
            $presets = self::presets($cc);
            if ($presets === [] || ($trunk !== '' && !in_array($trunk, self::trunkNames(), true))) {
                throw new \Exception(t('inbound_norm.err_country'));
            }
            $db = getDB();
            $exists = $db->prepare('SELECT id FROM pbx_inbound_norm_rules WHERE trunk_name <=> ? AND target = ? AND match_pattern = ?');
            $insert = $db->prepare('INSERT INTO pbx_inbound_norm_rules (trunk_name, target, rule_name, match_pattern, strip_front, prepend, is_active, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, NOW())');
            $added = 0;
            foreach ($presets as $r) {
                $scope = $trunk !== '' ? $trunk : null;
                $exists->execute([$scope, $r['target'], $r['match_pattern']]);
                if ($exists->fetchColumn() === false) {
                    $insert->execute([$scope, $r['target'], $r['rule_name'], $r['match_pattern'], (int) ($r['strip_front'] ?? 0), (string) ($r['prepend'] ?? ''), (int) ($r['is_active'] ?? 1)]);
                    $added++;
                }
            }
            self::markChanged("+{$cc}", 'create');
            return sprintf(t('inbound_norm.presets_loaded'), $added);
        });
    }

    public static function toggle(array $data): array
    {
        return PBXHelper::handleAction($data['csrf_token'] ?? '', function () use ($data) {
            $id = (int) ($data['rule_id'] ?? 0);
            getDB()->prepare('UPDATE pbx_inbound_norm_rules SET is_active = 1 - is_active WHERE id = ?')->execute([$id]);
            self::markChanged("#{$id}", 'update');
            return t('inbound_norm.saved');
        });
    }

    /**
     * What a number becomes on a trunk. As in the dialplan, the most specific pattern wins, and a
     * rule of this trunk comes before a rule for all trunks.
     *
     * @param list<array<string, mixed>> $rules
     * @return array{result: string, rule: string|null}
     */
    public static function simulate(array $rules, string $trunk, string $target, string $number): array
    {
        foreach ([$trunk, null] as $scope) {
            $best = null;
            $bestScore = -1;
            foreach ($rules as $r) {
                if (empty($r['is_active']) || $r['target'] !== $target || ($r['trunk_name'] ?: null) !== ($scope ?: null)) {
                    continue;
                }
                if (@preg_match(DialplanRuleRepository::asteriskPatternToRegex((string) $r['match_pattern']), $number) === 1) {
                    $score = DialplanRuleRepository::calculatePatternSpecificity((string) $r['match_pattern']);
                    if ($score > $bestScore) {
                        [$best, $bestScore] = [$r, $score];
                    }
                }
            }
            if ($best !== null) {
                return ['result' => $best['prepend'] . substr($number, (int) $best['strip_front']), 'rule' => (string) $best['rule_name']];
            }
            if ($scope === null) {
                break;
            }
        }
        return ['result' => $number, 'rule' => null];
    }

    private static function markChanged(string $label, string $action): void
    {
        markPendingSync('inbound_dialplan', 'inbound_norm', 0, $label, $action, $_SESSION['user_id'] ?? null);
    }
}
